 words:[W("热闹","rè|nao","คึกคัก / ครึกครื้น","เร่อ-เน่า","热 (ร้อน) + 闹 (อึกทึก) = บรรยากาศร้อนแรงเสียงดัง","节日里，街道上很热闹。","jié|rì lǐ, jiē|dào shàng hěn rè|nao.","ในวันเทศกาล บนถนนคึกคักมาก"),W("导游","dǎo|yóu","ไกด์นำเที่ยว","เต่า-โหย๋ว","导 (นำทาง) + 游 (เที่ยว) = คนนำเที่ยว","导游给我们介绍了很多故事。","Dǎo|yóu gěi wǒ|men jiè|shào le hěn|duō gù|shi.","ไกด์เล่าเรื่องราวให้เราฟังมากมาย"),W("参观","cān|guān","ไปเยี่ยมชม","ชาน-กวน","参 (เข้าร่วม) + 观 (ดู) = เข้าไปดู","明天我们去参观学校。","míng|tiān wǒ|men qù cān|guān xué|xiào.","พรุ่งนี้เราไปเยี่ยมชมโรงเรียน"),W("质量","zhì|liàng","คุณภาพ","จื้อ-เลี่ยง","质 (เนื้อแท้) + 量 (ปริมาณ/วัด) = วัดความดีของเนื้อ","这个包的质量很好。","Zhè|ge bāo de zhì|liàng hěn hǎo.","กระเป๋าใบนี้คุณภาพดีมาก"),W("合适","hé|shì","เหมาะ / พอดี","เหอ๋-ชื่อ","合 (เข้ากัน) + 适 (เหมาะ) = เข้ากันได้ดี","这双鞋我穿很合适。","Zhè shuāng xié wǒ chuān hěn hé|shì.","รองเท้าคู่นี้ฉันใส่พอดีมาก"),W("赚","zhuàn","ได้กำไร / หาเงิน","จ้วน","贝 (เงินเปลือกหอยโบราณ) ด้านซ้าย = เรื่องเงินทอง","他每个月赚很多钱。","Tā měi ge yuè zhuàn hěn|duō qián.","เขาหาเงินได้มากทุกเดือน"),W("浪费","làng|fèi","สิ้นเปลือง","ล่าง-เฟ่ย","浪 (คลื่น) + 费 (ใช้จ่าย) = ใช้เงินไหลไปเหมือนคลื่น","不要浪费时间。","Bú yào làng|fèi shí|jiān.","อย่าเสียเวลา"),W("数量","shù|liàng","จำนวน","ชู่-เลี่ยง","数 (นับ) + 量 (ปริมาณ) = จำนวนที่นับได้","东西的数量很多。","dōng|xi de shù|liàng hěn duō.","จำนวนของมีมาก")],
 sents:[["我们/别/浪费/时间/了。", "wǒ|men/bié/làng|fèi/shí|jiān/le.", "เราอย่าเสียเวลาเลย"], ["我们/别/浪费/钱/了。", "wǒ|men/bié/làng|fèi/qián/le.", "เราอย่าเปลืองเงินเลย"], ["我们/别/浪费/水/了。", "wǒ|men/bié/làng|fèi/shuǐ/le.", "เราอย่าใช้น้ำเปลืองเลย"], ["明天/我们/去/参观/学校。", "míng|tiān/wǒ|men/qù/cān|guān/xué|xiào.", "พรุ่งนี้เราไปเยี่ยมชมโรงเรียน"], ["东西/的/数量/很/多。", "dōng|xi/de/shù|liàng/hěn/duō.", "จำนวนของมีมาก"], ["节日/里，/街道/上/很/热闹。", "jié|rì/lǐ,/jiē|dào/shàng/hěn/rè|nao.", "ในวันเทศกาล บนถนนคึกคักมาก"]],
